def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """
    Solve the maze path problem from start to goal in the given grid.

    :param grid: List of grid strings where . is free cell and # is wall.
    :param start: Starting position as a tuple (row, col).
    :param goal: Goal position as a tuple (row, col).
    :return: List of (row, col) tuples forming the path from start to goal, or an empty list if no path exists.
    """
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if start[0] < 0 or start[0] >= rows or start[1] < 0 or (start[1] >= cols):
        raise ValueError(f'Start position ({start}) is out of bounds.')
    if goal[0] < 0 or goal[0] >= rows or goal[1] < 0 or (goal[1] >= cols):
        raise ValueError(f'Goal position ({goal}) is out of bounds.')
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        raise ValueError(f'Start or goal positions contain walls (' + grid[start[0]][start[1]] + ',' + grid[goal[0]][goal[1]] + ').')
    moves = [(0, 1), (0, -1), (-1, 0), (1, 0)]
    from collections import deque
    queue = deque([(start, [start])])
    visited = set()
    visited.add(start)
    start2path = {}
    path2start = {start: [start]}
    while queue:
        (curr_row, curr_col), path = queue.popleft()
        if (curr_row, curr_col) == goal:
            while path:
                if path[0] == [start]:
                    start2path[path[0]] = [curr_row, curr_col]
                    break
                path.pop(0)
            optimal_path = [start]
            current_positions = [start]
            while current_positions:
                for next_position in current_positions:
                    if next_position == goal:
                        return optimal_path
                    elif (next_position, [next_position]) in queue:
                        optimal_path.append(next_position)
                        current_positions = [start]
                        queue.remove((next_position, [next_position]))
                        break
                current_positions = [x for x in path2start if x not in queue]
            return optimal_path
        for move in moves:
            next_row, next_col = (curr_row + move[0], curr_col + move[1])
            if 0 <= next_row < rows and 0 <= next_col < cols and (grid[next_row][next_col] == '.') and ((next_row, next_col) not in visited):
                visited.add((next_row, next_col))
                new_path = path + [(next_row, next_col)]
                queue.append(((next_row, next_col), new_path))
                start2path[tuple(new_path)] = (next_row, next_col)
                path2start[next_row, next_col] = path
    return []

