def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    result = []
    visited = []
    stack = [start]
    while len(stack) > 0:
        current = stack.pop()
        if current == goal:
            break
        for neighbour in [(current[0] + 1, current[1]), (current[0] - 1, current[1]), (current[0], current[1] + 1), (current[0], current[1] - 1)]:
            if neighbour[0] < 0 or neighbour[0] >= len(grid) or neighbour[1] < 0 or (neighbour[1] >= len(grid[0])) or (grid[neighbour[0]][neighbour[1]] == '#') or (neighbour in visited):
                continue
            stack.append(neighbour)
            visited.append(neighbour)
    if current != goal:
        result.append(goal)
        block_current = True
        while current != start and block_current:
            for neighbour in [(current[0] + 1, current[1]), (current[0] - 1, current[1]), (current[0], current[1] + 1), (current[0], current[1] - 1)]:
                if neighbour in visited:
                    block_current = False
                    break
                if neighbour in visited:
                    continue
                stack.append(neighbour)
                visited.append(neighbour)
            current = stack.pop()
            if current == start:
                break
            result.append(current)
    result.reverse()
    return result

