    max_row = len(grid) - 1
    max_col = len(grid[0]) - 1
    visit = []

    def dfs(row, col) -> list[tuple[int, int]]:
        nonlocal visit
        visit[row, col] = True
        if (row, col) == goal:
            return True
        if (row, col) not in visit and row < max_row and (grid[row + 1][col] != '#'):
            b = dfs(row + 1, col)
            if b:
                return [tuple([row + 1, col])] + [tuple([row, col])]
        if (row, col) not in visit and row > 0 and (grid[row - 1][col] != '#'):
            b = dfs(row - 1, col)
            if b:
                return [tuple([row - 1, col])] + [tuple([row, col])]
        if (row, col) not in visit and col < max_col and (grid[row][col + 1] != '#'):
            b = dfs(row, col + 1)
            if b:
                return [tuple([row, col + 1])] + [tuple([row, col])]
        if (row, col) not in visit and col > 0 and (grid[row][col - 1] != '#'):
            b = dfs(row, col - 1)
            if b:
                return [tuple([row, col - 1])] + [tuple([row, col])]
        return False
    return dfs(start[0], start[1])

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    from collections import deque

    def get_cost(a: tuple[int, int]) -> int:
        return abs(a[0] - goal[0]) + abs(a[1] - goal[1])
    paths = deque([start])
    visited = {start: 0}
    solution = []
    while paths:
        node = paths.popleft()
        cost = visited[node]
        if node == goal:
            while node != start:
                solution.append(node)
                node = visited[node][0]
            return solution[::-1]
        new_positions = []
        for i in range(0, 3):
            if i == 1 or i == 2:
                hi = '+'
            elif i == 0:
                hi = node[0] - 1
            else:
                hi = node[0] + 1
            new_positions.append((hi, node[1]))
            if i == 0 or i == 3:
                lo = '+'
            elif i == 1:
                lo = node[1] - 1
            else:
                lo = node[1] + 1
            new_positions.append((node[0], lo))
        for pos in new_positions:
            if '.' in grid[pos[0]] or '+' == pos[0]:
                continue
            if not pos in visited:
                visited[pos] = (node, cost + get_cost(pos))
                paths.append(pos)
    return solution

