def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """ Solves grid-based maze problems """
    width = len(grid[0])
    height = len(grid)
    if width == 0 or width > 30 or height == 0 or (height > 30):
        raise ValueError
    i_neigh = ((-1, 0), (1, 0), (0, -1), (0, 1))

    def valid_neighbor(pos: tuple[int, int], neighbors: set[tuple[int, int]]) -> set[tuple[int, int]]:
        return neighbors & set([(row, col) for row, col in neighbors if row >= 0 and row < height and (col >= 0) and (col < width) and (grid[row][col] == '.')])
    solution_path = []
    frontier = set([start])
    explored = set([])
    prev = dict([start, None])
    while frontier:
        node = min(frontier, key=lambda node: len(prev[node] if node in prev else []))
        explored.add(node)
        if node == goal:
            goal_node = node
            break
        frontier.remove(node)
        neighbors = set()
        for drow, dcol in i_neigh:
            neighbors.add((node[0] + drow, node[1] + dcol))
        neighbors = valid_neighbor(node, neighbors)
        for neigh in neighbors:
            if neigh not in explored and neigh not in frontier:
                frontier.add(neigh)
                prev[neigh] = node
    while goal_node:
        goal_node, prev_node = (prev[goal_node], prev[prev_node])
        solution_path.append(prev_node)
    solution_path.extend([start])
    return solution_path

