def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    grid = {(row, col) for row, rowstr in enumerate(grid) for col, cell in enumerate(rowstr) if cell == '.'}
    path = []

    def backtrack(cur):
        if cur == start:
            return True
        for move in ((0, 1), (0, -1), (-1, 0), (1, 0)):
            next = (cur[0] + move[0], cur[1] + move[1])
            if not (next in grid and next not in path):
                continue
            path.append(next)
            if backtrack(next):
                return True
            path.pop()
        return False
    path.append(start)
    backtrack(start)
    return path if path[-1] == goal else []

