    - The length of the shortest path from s to t, or -1 if t is unreachable from s.

    Raises:
    - ValueError: If inputs are of incorrect type or do not meet constraints.
    """
    if not isinstance(n, int):
        raise TypeError('n must be an integer.')
    if not isinstance(edges, list):
        raise TypeError('edges must be a list.')
    if not isinstance(s, int):
        raise TypeError('s must be an integer.')
    if not isinstance(t, int):
        raise TypeError('t must be an integer.')
    if n < 1 or s < 0 or t < 0:
        raise ValueError('n, s and t must be non-negative.')
    if t >= n or s >= n:
        raise ValueError('s and t must be less than the number of nodes, n.')
    weights = [[float('inf') for _ in range(n)] for _ in range(n)]
    for node in range(n):
        weights[node][node] = 0
        for i in range(len(edges)):
            node1, node2, weight = edges[i]
            if node == node1:
                weights[node][node2] = weight
    for node in range(n):
        for node1 in range(n):
            for node2 in range(n):
                if weights[node][node2] > weights[node][node1] + weights[node1][node2]:
                    weights[node][node2] = weights[node][node1] + weights[node1][node2]
    if s == t:
        return 0
    if weights[s][t] in [float('inf'), float('inf')]:
        return -1
    return int(weights[s][t])

def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    g = {node: set() for node in range(n)}
    q: list[int] = []
    weights: dict[int, int] = {node: -1 for node in range(n)}
    for e in edges:
        g[e[0]].add((e[1], e[2]))
    weights[s] = 0
    q.append(s)
    while q:
        cur = q.pop(0)
        for e in g[cur]:
            if weights[e[0]] == -1:
                weights[e[0]] = weights[cur] + e[1]
                q.append(e[0])
    return weights[t]

