        cell = list(cell)
        return cell[0] * self.size + cell[1]

    def add_neighbour(self, grid, vertex: tuple[int, int]) -> None:
        north = (max(vertex[0] - 1, self.very_north), vertex[1])
        south = (min(vertex[0] + 1, self.size - 1), vertex[1])
        west = (vertex[0], max(vertex[1] - 1, self.very_west))
        east = (vertex[0], min(vertex[1] + 1, self.size - 1))
        crowded_neighbours = {grid.get(k) for k in (north, south, west, east)}
        loners = [n for n in crowded_neighbours if n in self.available]
        if loners:
            self.available.remove(loners[0])
        self.add_ne(cell, neighbours)

    def keys_defined_at(self, cell: tuple[int, int]) -> list[tuple[int, int]]:
        cell = cell
