def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    if n == 1:
        return 0
    if t in {s for u, v, w in edges} and s in {u for u, v, w in edges}:
        return -1
    queue = [(s, 0)]
    visited = {s}
    while queue:
        node, path_len = queue.pop(0)
        if node not in visited:
            for edge in edges:
                if edge[0] == node:
                    queue.append((edge[1], path_len + edge[2]))
                    visited.add(node)
        if node == t:
            return path_len
    return -1

