def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    distance = [n ** 2] * n
    distance[s] = 0
    prio_queue = [(0, s)]
    while len(prio_queue) > 0:
        curr_dist, curr_node = min(prio_queue)
        prio_queue.remove((curr_dist, curr_node))
        if curr_dist > distance[curr_node]:
            continue
        for neighbour_pair in edges:
            if neighbour_pair[0] == curr_node:
                new_distance = curr_dist + neighbour_pair[2]
                if new_distance < distance[neighbour_pair[1]]:
                    distance[neighbour_pair[1]] = new_distance
                    while neighbour_pair[1] in prio_queue:
                        prio_queue.remove((curr_dist, neighbour_pair[1]))
                    prio_queue.append((new_distance, neighbour_pair[1]))
    return distance[s] if distance[s] < n ** 2 else -1

