def _solve(n: int, adj_list: list[list[tuple[int, int]]], u: int, t: int, visited: list[bool]) -> int:
    visited[u] = True
    shortest = float('+inf')
    for v, w in adj_list[u]:
        if v == t and w < shortest:
            shortest = w
        elif visited[v] == False:
            result = _solve(n, adj_list, v, t, visited)
            if result >= 0 and w + result < shortest:
                shortest = w + result
    visited[u] = False

    return -1 if shortest == float('+inf') else shortest

