def create_graph(n: int, edges: list[tuple[int, int, int]]) -> dict[int, list[tuple[int, int]]]:
    graphs = {}
    for node in range(0, n):
        graphs[node] = []

    for edge in edges:
        start_node = edge[0]
        end_node = edge[1]
        weight = edge[2]

        graphs[start_node].append((end_node, weight))
