def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    from collections import defaultdict
    from heapq import heappop, heappush
    adjacency_list = defaultdict(lambda: defaultdict(int))
    for u, v, weight in edges:
        adjacency_list[u][v] = weight
    visited = set()
    distances = {node: float('inf') for node in range(n)}
    distances[s] = 0
    priority_queue = [(0, s)]
    while priority_queue:
        current_distance, current_node = heappop(priority_queue)
        if current_node == t:
            return current_distance
        if current_node in visited:
            continue
        visited.add(current_node)
        for neighbor, weight in adjacency_list[current_node].items():
            if current_distance + weight < distances[neighbor]:
                distances[neighbor] = current_distance + weight
                heappush(priority_queue, (distances[neighbor], neighbor))
    return distances[t]
