def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    if s == t:
        return 0
    parents, visited = ([-1] * n, [False] * n)
    visited[s] = True
    parent = s
    shortest = 2 ** (n ** 2 + 1)
    while parent != -1:
        parent = -1
        for u, v, w in edges:
            if not visited[v] and parents[v] == u:
                if v == t:
                    if w < shortest:
                        shortest = w
                        visited[v] = True
                else:
                    parents[v] = u
                    parent = v
    return -1 if shortest == 2 ** (n ** 2 + 1) else shortest

def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    """
    Find shortest path between s and t, utilizing path relaxation

    :param n: number of nodes
    :param edges: list of paths as (u, v, w) tuples
    :param s: shortest path start
    :param t: shortest path end
    :returns: length of shortest path from s to t or -1 if no path exists
             0 if s == t
    """
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
    distance = [float('inf') for _ in range(n)]
    distance[s] = 0
    visited = set()

    def relax(start: int):
        for end, w in graph[start]:
            if distance[start] != float('inf'):
                distance[end] = min(distance[end], distance[start] + w)
        visited.add(start)
    relax(s)
    while visited:
        next_start = None
        for node in visited:
            if not next_start or distance[node] < distance[next_start]:
                next_start = node
        next_visited = set()
        for end, w in graph[next_start]:
            if distance[end] > distance[next_start] + w:
                distance[end] = distance[next_start] + w
                next_visited.add(end)
        if next_start in next_visited:
            visited = next_visited
    return distance[t] if distance[t] != float('inf') else -1

def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    known = [False for _ in range(n)]
    dist_from_s = [float('inf') for _ in range(n)]
    dist_from_s[s] = 0
    known[s] = True
    to_explore = [s]
    for _ in range(n):
        next_to_explore = []
        for i in range(len(to_explore)):
            current_to_explore = to_explore[i]
            for v, w in edges:
                if current_to_explore == v:
                    if dist_from_s[w] > dist_from_s[v] + 1:
                        dist_from_s[w] = dist_from_s[v] + 1
                        next_to_explore.append(w)
            known[current_to_explore] = True
            to_explore.pop(0)
        to_explore = next_to_explore
    return dist_from_s[t]

def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    """
    Edge case checking.
    """
    if s == t:
        return 0
    if not n or not edges:
        return -1
    '\n    Initialize nodes distance from s to 10^4\n    dist[u] = shortest path from s to u\n    dist[s] = 0\n    '
    dist = {}
    for node in range(0, n):
        dist[node] = 10000
    dist[s] = 0
    '\n    Create a list of adjancency lists for the edges. index = u in edge (u, v, weight); adj[u] = [(v1, w1) …]\n    '
    adj = []
    for u in range(0, n):
        adj.append([])
    for u, v, w in edges:
        adj[u].append((v, w))
    '\n    Relaxing all edges (n-1) times to eliminate the longest edges from the solution path.\n    '
    for _ in range(0, n - 1):
        for u in range(0, n):
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
    '\n    If the edge s -> t has been relaxed again, then the graph contains a negative weight edge cycle, whence no shortest-path solution is possible. Return -1.\n    '
    if dist[t] > dist[s] + 1:
        return -1
    '\n    Return distance from s to t.\n    '
    return dist[t]

