from collections import defaultdict, deque

def build_graph(edges):
    """Build graph from adjacency list 'edges' stored as (u,v,d) tuple."""
    g = defaultdict(list)
    for u, v, d in edges:
        g[u].append((v, d))
    return g

def __shortest_path(g, s):
    dist, visited, q = ([float('inf')] * len(g), set(), deque([s]))
    dist[s] = 0
    while q:
        u = q.popleft()
        if u in visited:
            continue
        visited.add(u)
        for v, d in g[u]:
            t = d + dist[u]
            if dist[v] > t:
                dist[v] = t
                q.append(v)
    return dist

