    adj = [[] for _ in range(n)]
    heap = []
    for u, v, w in edges:
        adj[u].append((v, w))
    heappush(heap, (0, s))
    while heap:
        d, v = heappop(heap)
        if d < dist[v]:
            dist[v] = d
            for w, c in adj[v]:
                if dist[w] > dist[v] + c:
                    heappush(heap, (dist[v] + c, w))
    return dist[t] if dist[t] < 545713491727 else -1
