    def bfs(grid: list[str], start: tuple[int, int]) -> dict[tuple[int, int], tuple[int, int]]:
        """Breadth-first search of `grid` from `start`."""
        visited = {}
        queue = list()
        queue.insert(0, start)
        while queue:
            r, c = queue.pop()
            if (r, c) not in visited:
                visited[(r, c)] = None
                # check for neighbours
                if r > 0 and (r - 1, c) not in visited and grid[r - 1][c] != "#":
                    queue.insert(0, (r - 1, c))
                if r < len(grid) - 1 and (r + 1, c) not in visited and grid[r + 1][c] != "#":
                    queue.insert(0, (r + 1, c))
                if c > 0 and (r, c - 1) not in visited and grid[r][c - 1] != "#":
                    queue.insert(0, (r, c - 1))
                if c < len(grid[0]) - 1 and (r, c + 1) not in visited and grid[r][c + 1] != "#":
                    queue.insert(0, (r, c + 1))

        return visited

    # `prev_to` houses the predecessor of `(r, c)` in a valid path from `start` to `(r, c)`
    prev_to: dict[tuple[int, int], tuple[int, int]] = bfs(grid, start)

    # `prev_to` does not have `goal`
    if goal not in prev_to:
        return []

    path = list()
    curr_goal = goal
    while prev_to[curr_goal] is not None:
        path.insert(0, curr_goal)
        curr_goal = prev_to[curr_goal]

