def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    if start == goal:
        return [start]

    def traverse(i, j):
        if (i, j) == goal:
            return [(i, j)]
        traverse.queue.append((i, j))
        for r, c in [(i, j - 1), (i, j + 1), (i + 1, j), (i - 1, j)]:
            if len(grid) - 1 >= r >= 0 and len(grid[0]) - 1 >= c >= 0 and (grid[r][c] == '.') and ((r, c) not in traverse.last_r_c_set):
                traverse.last_r_c_set.add((r, c))
                traverse.queue.append((r, c))
                if traverse.dist[r, c] > traverse.dist[i, j] + 1:
                    traverse.dist[r, c] = traverse.dist[i, j] + 1
                    traverse.after[r, c] = [(i, j)]
                else:
                    traverse.after[r, c] += [(i, j)]
        while len(traverse.last_r_c_set) < len(traverse.queue) and (r, c) != start:
            r, c = traverse.queue.pop(0)
        if (r, c) == start:
            traverse.queue = []
        traverse.last_r_c_set = set()
    traverse.dist = {(i, j): 999999 for i in range(len(grid)) for j in range(len(grid[0]))}
    traverse.dist[start] = 0
    traverse.after = dict.fromkeys(list(traverse.dist), [])
    traverse.after[start] = [(0, 0)]
    traverse.last_r_c_set, traverse.queue = (set(), [start])
    while traverse.queue:
        i, j = traverse.queue.pop(0)
        traverse(i, j)
    if goal not in traverse.after:
        return []
    return [start] + traverse.after[goal][::-1] + [goal]

def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """Function returning a list of tuples on a path starting at start.
    """

    def in_grid(cell: tuple[int, int]) -> bool:
        return 0 <= cell[0] < len(grid) and 0 <= cell[1] < len(grid[0])

    def valid(grid: list[str], cell: tuple[int, int]) -> bool:
        """Valid return True iff trying to move to cell is a valid move.

        Args :
        cell : the cell to move to

        Returns :
        True if moving to cell is a valid move, False otherwise
        """
        valid_chars = ('#', '.', '+')
        return grid[cell[0]][cell[1]] in valid_chars

    def search(grid, start, goal):
        paths = [[start]]
        screen = []
        while len(paths) != 0:
            new_paths = []
            for path in paths:
                current = path[-1]
                if current == goal:
                    return path
                for d in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    next = (current[0] + d[0], current[1] + d[1])
                    if valid(grid, current) and in_grid(next) and (grid[next[0]][next[1]] != '#') and (next not in screen):
                        next_path = path[:]
                        next_path.append(next)
                        new_paths.append(next_path)
            paths = new_paths
        return []
    grid = [list(row) for row in grid]
    path = search(grid, start, goal)
    if path:
        path = [(index[0], index[1]) for index in path]
    return path

