    visits = [start]
    neighboursTuplas = neighbours(grid, start)
    while visits:
        newV = []
        for v in visits:
            if v == goal:
                pathToStar = [v]
                while v != start:
                    currentV = v
                    opV = previous[currentV]
                    pathToStar.append(opV)
                    v = opV
                pathToStar.reverse()
                return pathToStar
            for neighbour in neighboursTuplas:
                if neighbour not in previous and neighbour not in visits:
                    newV.append(neighbour)
                    previous[neighbour] = v
            neighboursTuplas = neighbours(grid, v)
        visits = newV
    return []

