def solve(grid: list[str], start: tuple[int, int], goal: tuple[int, int]) -> list[tuple[int, int]]:
    """Search the grid for shortest path from start to goal."""
    width = len(grid[0])
    frontier = [start]
    previous = {}
    while True:
        frontier = sorted(frontier, key=lambda cell: manhattan_distance(cell, goal))
        if not frontier:
            break
        try:
            current = frontier.pop(0)
        except IndexError:
            current = None
        if current and current == goal:
            path = [current]
            while current != start:
                current = previous.get(current)
                if current is None:
                    break
                path.append(current)
            break
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            neighbour = (current[0] + dx, current[1] + dy)
            if neighbour[0] >= 0 and neighbour[0] < width and (neighbour[1] >= 0) and (neighbour[1] < len(grid)):
                if grid[neighbour[1]][neighbour[0]] != '#':
                    neighbour in frontier or frontier.append(neighbour)
                    previous[neighbour] = current
    path.reverse()
    return path

def manhattan_distance(a: tuple[int, int], b: tuple[int, int]) -> int:
    """Return Manhattan distance between two points."""
    ax, ay = a
    bx, by = b
    return abs(ax - bx) + abs(ay - by)
