def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    import heapq
    INF = float('inf')
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
    dist = [INF] * n
    queue = [(0, s)]
    dist[s] = 0
    while queue:
        current_dist, current_node = heapq.heappop(queue)
        if current_dist > dist[current_node]:
            continue
        for next_node, next_dist in graph[current_node]:
            new_dist = current_dist + next_dist
            if new_dist < dist[next_node]:
                dist[next_node] = new_dist
                heapq.heappush(queue, (new_dist, next_node))
    if s == t:
        return 0
    elif dist[t] == INF:
        return -1
    else:
        return dist[t]

