def _dist_weight(start: int, end: int, num_nodes:int, edge_list:list[tuple[int, int, int]]) -> int: 
    """Process nodes topologically using Graph-Aware-BFS. return dist from start node to each reachable end node"""

    # Are start and end even existent?
    if start < 0 or start >= num_nodes or end < 0 or end >= num_nodes:
        raise ValueError("START and END nodes should only be > 0 and <= number of nodes.")

    node_adj_list = _create_edge_list(num_nodes, edge_list)

    # Continue if all our nodes have a starting point, otherwise return -1 for each unknown ones:
    if not node_adj_list.get(0):
        raise ValueError("INVALID graph input: Cannot reach any nodes: node 0 not found")

    unvisited_q = []
    last_visit = {i: i for i in range(num_nodes)}
    dist = [[float("inf")] * num_nodes for _ in range(num_nodes)]

    def in_order(v: int) -> None:
        """Insert nodes in acyclicity order"""
        unvisited_q.append(v)


    def visit() -> None:
        """Visit next unvisited node w/ known predecessor"""
        visitable = set()

        data = unvisited_q.pop(0)
        for u, _ in node_adj_list.get(data,[]):
            unvisited_q.append(u) # mark all directly connected unavailable
            visitable.add(u)

        for u in visitable:
            in_order(u)
        return last_visit[max(visit_free,last_visit[data])]


    def on_queue(v: int) -> bool:
        """Check if a node is waitlisted pending processing"""
        return unvisited_q.count(v) > 1


    in_order(0)

    while (v := visit()):
        # Check if current node is connected to next node to be processed
        if v_connectable := (next_node := visit(), last_visit[next_node] == last_visit[v]):
            for u in (u for u,_ in node_adj_list.get(v,[])):
                if on_queue(u):
                    _dist_weight(u, next_node, num_nodes, edge_list)
                min_cost, _, start_node = min(_dist_weight(u,v,num_nodes,edge_list), key = lambda d: d[0]) # fastest dist to v so far
                i, j = last_visit[v], last_visit[next_node]
                dist[i][j] = min(dist[i][j], min_cost)
        last_visit[next_node] = last_visit[v]

    return dist[start][end]

def _reset_dist(dist: list[float]) -> list[float]:
    """Set distance between points as unconnected"""
    for i,j in _create_edge_list(len(dist), dist):
        dist[i][j] = float("inf")
    return dist

