def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    from heapq import heapify, heappush, heappop
    pq = [(0, s)]
    dist = [100000000 for _ in range(n)]
    dist[s] = 0
    heapify(pq)
    while pq:
        ua, u = heappop(pq)
        if ua > dist[u]:
            continue
        for v, w in edges[u]:
            alt = ua + w
            if alt < dist[v]:
                dist[v] = alt
                heappush(pq, (alt, v))
    return -1 if dist[t] == 100000000 else dist[t]

