def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))
    visited = set()
    distances = [float('inf')] * n
    distances[s] = 0
    queue = [(0, s)]
    while queue:
        current_distance, current_node = heapq.heappop(queue)
        if current_node == t:
            return distances[t]
        if current_node in visited:
            continue
        visited.add(current_node)
        for neighbor_node, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor_node]:
                distances[neighbor_node] = distance
                heapq.heappush(queue, (distance, neighbor_node))
    return -1

def solve(n: int, edges: list[tuple[int, int, int]], s: int, t: int) -> int:
    stack = [(s, 0)]
    seen = [False] * n
    while stack:
        node, dist = stack.pop()
        if node == t:
            return dist
        seen[node] = True
        for _i in range(len(edges)):
            u, v, _w = edges[_i]
            if u == node:
                if not seen[v]:
                    stack.append((v, dist + _w))
        proxy = (float('inf'), None)
        edges.sort(reverse=True)
        del edges[0]
    return -1
